observation.command:
cat > /tmp/validate-interact.mjs << 'EOF'
import { chromium } from '/workspace/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const pageErrors = [];
page.on('pageerror', (e) => pageErrors.push(String(e)));

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(1500);

// Baseline: canvas area text before adding a module
const before = await page.evaluate(() => document.body.innerText.includes('Ergänzen Sie eines der folgenden Elemente in die Arbeitsfläche'));

// Click the "Einzeiliges Textfeld" module button in the palette
await page.getByRole('button', { name: 'Einzeiliges Textfeld' }).first().click();
await page.waitForTimeout(1500);

const after = await page.evaluate(() => {
  const t = document.body.innerText;
  return {
    stillEmptyPlaceholder: t.includes('Ergänzen Sie eines der folgenden Elemente in die Arbeitsfläche'),
    hasEinzeiliges: t.includes('Einzeiliges Textfeld'),
    hasBearbeiten: t.includes('Formular bearbeiten'),
    hasAbschnitt: t.includes('Formularabschnitte verwalten'),
    hasDeleteButton: document.body.innerText.includes('Löschen') || document.querySelectorAll('button[aria-label*="löschen" i], button[title*="löschen" i]').length,
  };
});
await page.screenshot({ path: '/tmp/formulardesigner-after-add.png', fullPage: true });
console.log('BEFORE_EMPTY_PLACEHOLDER:', before);
console.log('AFTER:', JSON.stringify(after));
console.log('PAGE_ERRORS:', JSON.stringify(pageErrors));
await browser.close();
EOF
node /tmp/validate-interact.mjs; echo "EXIT: $?"
